@push('scripts')<script>(()=>{const root=document.querySelector('#import-progress');if(!root)return;const terminal=['completed','completed_with_warnings','failed','rolled_back'];const poll=async()=>{try{const r=await fetch(root.dataset.statusUrl,{headers:{Accept:'application/json'}}),d=await r.json(),labels={queued:'Importavimas laukia eilėje',running:'Importuojama',completed:'Baigta',completed_with_warnings:'Baigta su perspėjimais',failed:'Nepavyko'};document.querySelector('#import-state').textContent=labels[d.status]||d.status;document.querySelector('#import-stage').textContent=d.stage||'';document.querySelector('#import-percent').textContent=d.percentage+'%';const bar=document.querySelector('#import-bar');bar.style.width=d.percentage+'%';bar.setAttribute('aria-valuenow',d.percentage);document.querySelector('#import-processed').textContent=d.processed+' / '+d.total;for(const k of ['created','updated','skipped','failed'])document.querySelector('#import-'+k).textContent=d[k];document.querySelector('#import-media').textContent=d.media_copied+' / '+d.media_reused;document.querySelector('#worker-warning').hidden=!d.queue_stalled;if(terminal.includes(d.status)){document.querySelector('#result-link').hidden=false;return}}catch(e){}setTimeout(poll,3000)};poll()})();</script>@endpush
